def sync_directory(db, bus, tenant, batch, old_count, full_list=False):
    if not batch and old_count > 0:
        raise SyncRejected("empty list for a non-empty directory")
    if full_list and len(batch) < 0.5 * old_count:
        raise SyncRejected("shrink guard: list under 50% of snapshot")
    if any(r.tenant != tenant for r in batch):
        raise SyncRejected("foreign tenant id in batch")
    leavers, groups, users = [], [], []
    with db.transaction():
        for r in batch:
            cur = db.execute(
                '''INSERT INTO directory_user(tenant_id,scim_id,email,email_verified,active,modified_at)
                   VALUES (%s,%s,%s,%s,%s,%s)
                   ON CONFLICT (tenant_id,scim_id) DO UPDATE SET email=EXCLUDED.email,
                     email_verified=EXCLUDED.email_verified, active=EXCLUDED.active,
                     modified_at=EXCLUDED.modified_at
                   WHERE directory_user.modified_at < EXCLUDED.modified_at''',
                (tenant, r.scim_id, r.email, r.email_verified, r.active, r.modified_at))
            if cur.rowcount == 0:
                continue                      # replay of an older or equal record: no change
            (users if r.kind == "user" and r.active else groups if r.kind == "group" else leavers).append(r)
        db.execute("UPDATE directory_cursor SET cursor=%s, committed_at=now() WHERE tenant_id=%s",
                   (batch[-1].cursor, tenant))   # cursor moves only inside the same commit
    # tricky part: order matters. A leaver must reach the revocation cache before anything else.
    for r in leavers: bus.publish("acl.leaver", r)
    for r in groups:  bus.publish("acl.group", r)
    for r in users:   bus.publish("acl.identity", r)
    return SyncResult(len(leavers), len(groups), len(users))

