def expand_group(db, tenant, gid, lazy_t=10_000, max_depth=20):
    visited, users = set(), set()
    stack = [(gid, 0)]
    while stack:                                    # explicit stack: no recursion limit surprises
        g, depth = stack.pop()
        if g in visited:
            continue                                # tricky part: the visited set is what breaks cycles
        if depth > max_depth:
            raise DataError(f"group nesting over {max_depth} at {g}")
        visited.add(g)
        for kind, member in db.execute(
                "SELECT member_kind, member_id FROM group_edge WHERE tenant_id=%s AND group_id=%s", (tenant, g)):
            if kind == "user":
                users.add(member)
                if len(users) > lazy_t:             # too big: store a reference, not the members
                    return _write(db, tenant, gid, None, lazy=True)
            elif member not in visited:
                stack.append((member, depth + 1))
    return _write(db, tenant, gid, sorted(users), lazy=False)

def _write(db, tenant, gid, members, lazy):
    v = db.execute("SELECT coalesce(max(membership_version),0)+1 FROM group_snapshot "
                   "WHERE tenant_id=%s AND group_id=%s", (tenant, gid)).fetchone()[0]
    db.execute("INSERT INTO group_snapshot(tenant_id,group_id,membership_version,members,lazy) VALUES (%s,%s,%s,%s,%s)",
               (tenant, gid, v, members, lazy))
    for u in members or []:
        db.execute('''INSERT INTO user_groups(tenant_id,user_id,group_id,membership_version) VALUES (%s,%s,%s,%s)
                      ON CONFLICT (tenant_id,user_id,group_id) DO UPDATE SET membership_version=EXCLUDED.membership_version''',
                   (tenant, u, gid, v))
    return Snapshot(v, members, lazy)

